import java.util.*;

class Solution {
    public List<List<Integer>> allOrderings(int[] nums) {
        List<List<Integer>> out = new ArrayList<>();
        go(nums, new boolean[nums.length], new ArrayList<Integer>(), out);
        return out;
    }

    private void go(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> out) {
        if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            used[i] = true;                 // choose
            cur.add(nums[i]);
            go(nums, used, cur, out);       // explore
            cur.remove(cur.size() - 1);     // un-choose
            used[i] = false;
        }
    }
}

