class Solution:
    def allOrderings(self, nums: List[int]) -> List[List[int]]:
        out, cur, used = [], [], [False] * len(nums)
        def go():
            if len(cur) == len(nums): out.append(cur[:]); return
            for i, x in enumerate(nums):
                if used[i]: continue
                used[i] = True; cur.append(x); go(); cur.pop(); used[i] = False
        go()
        return out

