function allOrderings(nums) {
  if (nums.length <= 1) return [nums.slice()];
  const out = [];
  nums.forEach((x, i) => { for (const p of allOrderings(nums.filter((_, j) => j !== i))) out.push([x, ...p]); });
  return out;
}
